/* "08:00 AM" → "08:00" for <input type="time"> */
function dsTimeToInput(t) {
  if (!t) return '';
  if (t.includes('AM') || t.includes('PM')) {
    const [time, ampm] = t.split(' ');
    let [h, m] = time.split(':');
