        <span>${rsEsc(schoolName)}${schoolAddr ? ` · ${rsEsc(schoolAddr)}` : ''}</span>
        <span>Confidential · ${rsEsc(schoolName)}</span>
      </div>
    </div>`;
  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
