          rollNo:    nm.rollNo || c.registrationNumber || c.RegistrationNumber || c.studentID || c.StudentID,
          name:      nm.name   || c.studentName || c.StudentName || '',
          father:    nm.father || c.fatherName || c.FatherName || '',
          mainObt:   num(main.obtainedMarks ?? main.ObtainedMarks),
          mainTotal: num(main.totalMarks ?? main.TotalMarks),
          subs: subArr.map(s => ({
            name:   s.examName ?? s.ExamName ?? '',
            subObt: num(s.originalObtained ?? s.OriginalObtained),
            origT:  num(s.originalTotal ?? s.OriginalTotal),
            conv:   num(s.convertedObtained ?? s.ConvertedObtained),
            weight: num(s.weightage ?? s.Weightage),
          })),
          grandObt:   num(c.grandObtained ?? c.GrandObtained),
          grandTotal: num(c.grandTotal ?? c.GrandTotal),
          pct:        num(c.percentage ?? c.Percentage),
          grade:      c.grade ?? c.Grade ?? '—',
          rank:       String(c.ranking ?? c.Ranking ?? '—'),
        };
      });
      setCbrResults(prev => prev.map(g => g.id === cr.id ? { ...g, students, studentsLoaded: true } : g));
    } catch (e) {
      console.error('Error loading combined-result students:', e);
      toast('Could not load students', 'error');
    } finally {
      setCbrStudentsLoading(p => { const n = { ...p }; delete n[cr.id]; return n; });
    }
  };

  /* Real per-subject main-exam marks for the open card (loaded on demand below,
     after the cbr UI state is declared). */
  const [cbrCardMarks, setCbrCardMarks] = useState(null); // { subjects:[names], totals:{}, obtained:{} }

  /* Download a student's combined result (API 13). */
  const cbrDownloadStudent = async (cr, st) => {
    try {
      const r = await cbrApi.getDownloadLink({ subExamIDs: cr.subExamIDs, studentID: st.studentID });
      if (r?.filePath) window.open(r.filePath, '_blank');
      else toast('Report not available yet', 'info');
    } catch (e) {
      if (e.status === 404) toast('Report not available yet', 'info');
      else { console.error('Error downloading result:', e); toast('Could not download report', 'error'); }
    }
  };

  /* Exams across ALL terms for the combined-create modal (so the user can pick a
     main/sub exam from any term, labelled "exam (term)"). */
  const [cbrAllExams, setCbrAllExams] = useState([]);
  const cbrBuildExams = (rows) => {
    const acc = {};
    (rows || []).forEach(ex => {
      const key = `${ex.examName}_${ex.termID}`;
      if (!acc[key]) acc[key] = { name: ex.examName, termID: ex.termID, termName: ex.termName, selectExam: ex.selectExam, from: ex.dateFrom, to: ex.dateTo, gradeName: ex.gradeName, classes: new Map() };
      acc[key].classes.set(String(ex.sectionID), {
        id: ex.id, classID: ex.classID, sectionID: ex.sectionID, sectionName: ex.sectionName, gradeName: ex.gradeName,
        className: `${ex.gradeName || ''}${ex.sectionName ? ' - ' + ex.sectionName : ''}`.trim(),
      });
    });
    return Object.values(acc).map(e => ({ ...e, classes: Array.from(e.classes.values()) }));
  };
  const loadAllTermExams = async () => {
    const token = sessionStorage.getItem('token');
    const bID = sessionStorage.getItem('branchID');
    const empID = sessionStorage.getItem('employee_ID');
    const headers = { Authorization: `Bearer ${token}`, Accept: 'application/json' };
    try {
      const tRes = await fetch(buildUrl('/api/termscrud'), {
        method: 'POST',
        headers: { ...headers, 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: 0, branchID: Number(bID), term: '', sessionYearID: termsSessionYearID(), action: 'get' }),
      });
      const tJson = await tRes.json();
      const termArr = Array.isArray(tJson) ? tJson : (tJson?.data || []);
      const termIds = termArr.map(t => t.id ?? t.ID ?? t.termID).filter(v => v != null);
      const lists = await Promise.all(termIds.map(tid =>
        fetch(buildUrl(`/api/getexamsbybranchidtermid?branchID=${bID}&termID=${tid}&empID=${empID}`), { headers })
          .then(r => r.json()).catch(() => []),
      ));
      const built = cbrBuildExams(lists.flat());
      setCbrAllExams(built);
      return built;
    } catch (e) { console.error('Error loading all-term exams:', e); return []; }
  };
  const [cbrFilterClass, setCbrFilterClass] = useState('');
  const [cbrClassList, setCbrClassList]     = useState([]); // [{ id, name, sections }] — class dropdown ke liye
  const cbrClassesLoaded = useRef(false);

  // Combined tab par class list (get-classlist-...) fetch karke dropdown bharo.
  const loadCbrClassList = async () => {
    try {
      const branchID = sessionStorage.getItem('branchID');
      const empID    = sessionStorage.getItem('employee_ID');
      const token    = sessionStorage.getItem('token');
      const r = await fetch(buildUrl(`/get-classlist-sectionlist-studentlist-by-branch/${branchID}/${empID}`),
        { headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' } });
      const data = await r.json();
      const arr = Array.isArray(data) ? data : (data?.data || []);
      setCbrClassList(arr);
    } catch (e) {
      console.error('Could not load combined class list', e);
      setCbrClassList([]);
    }
  };
  useEffect(() => {
    if (tab === 'results' && rsTab === 'combinedassessment' && !cbrClassesLoaded.current) {
      cbrClassesLoaded.current = true;
      loadCbrClassList();
    }
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [tab, rsTab]);

  const [cbrActiveGroup, setCbrActiveGroup] = useState(null);
  const [cbrOpenKey, setCbrOpenKey]       = useState(null);
  const [cbrCardCtx, setCbrCardCtx]       = useState(null); // { groupId, classId, studentRollNo }
  const [cbrConfirmPublish, setCbrConfirmPublish] = useState(null); // { classId, className, published }
  const [cbrConfirmDelete, setCbrConfirmDelete]   = useState(null); // { classId, className }
  const [cbrCreateOpen, setCbrCreateOpen]         = useState(false);
  const [cbrReportReq, setCbrReportReq]           = useState(null); // { classId, className }

  /* When a class row expands, lazy-load its students (card-per-student). */
  useEffect(() => {
    if (!cbrOpenKey) return;
    const cr = cbrResults.find(g => g.id === cbrOpenKey);
    if (cr && !cr.studentsLoaded) loadCbrStudents(cr);
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [cbrOpenKey]);

  /* Load all-term exams when the combined-create modal opens. */
  useEffect(() => {
    if (cbrCreateOpen) loadAllTermExams();
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [cbrCreateOpen]);

  /* When a single-assessment card opens, load that student's real per-subject marks. */
  useEffect(() => {
    if (!resCardCtx) { setResCardMarks(null); return undefined; }
    setResCardMarks(null); // pehle clear — sirf API data dikhe, static/stale flash na ho
    const { classID, sectionID, selectExam, termID, studentId } = resCardCtx;
    let cancelled = false;
    (async () => {
      try {
        const rawSubs = await cbrApi.getMainExamSubjects({ classID, sectionID, termID, examID: selectExam });
        // This API returns subjectName=null, so resolve names by subjectID from the syllabus list.
        const nameMap = {};
        try {
          const syl = await getSyllabusSubjects(classID, sectionID);
          (syl || []).forEach(s => { nameMap[s.subjectID] = s.subjectName; });
        } catch (e) { /* keep going with whatever names we have */ }
        const subs = rawSubs.map(su => ({
          ...su,
          subjectName: su.subjectName || nameMap[su.subjectID] || `Subject ${su.subjectID}`,
        }));
        const token = sessionStorage.getItem('token');
        const headers = { Authorization: `Bearer ${token}`, Accept: 'application/json' };
        // Direct marks fetch taa-ke obtain + remarks dono mil sakein
        const records = await Promise.all(subs.map(async su => {
          try {
            const p = new URLSearchParams({
              classID: String(classID), termID: String(termID ?? ''), ExamID: String(selectExam),
              SubjectID: String(su.subjectID), StudentID: String(studentId), sectionID: String(sectionID), pageNo: '1',
            });
            const r = await fetch(buildUrl(`/api/getsauploadmarksbyclassandtermandexamandsubject?${p}`), { headers });
            const d = await r.json();
            const rec = Array.isArray(d) ? d[0] : (d?.data?.[0] || null);
            return { su, rec };
          } catch { return { su, rec: null }; }
        }));
        if (cancelled) return;
        const obtained = {}, totals = {}, remarks = {};
        records.forEach(({ su, rec }) => {
          obtained[su.subjectName] = Number(rec?.obtainMarks ?? rec?.obtainedMarks ?? 0);
          totals[su.subjectName]   = Number(rec?.totalMarks ?? su.totalMarks ?? 0);
          if (rec?.remarks) remarks[su.subjectName] = rec.remarks;   // saved remarks → Comment column
        });
        // Student ka FINAL remark (getremarksbystudentfilters) → card ke Final Remarks mein
        let finalRemark = '';
        try {
          const branchID = sessionStorage.getItem('branchID');
          const fp = new URLSearchParams({
            branchID: String(branchID), classID: String(classID), sectionID: String(sectionID),
            examID: String(selectExam), termID: String(termID ?? ''), studentID: String(studentId),
            pageNo: '1', pageCount: '20',
          });
          const fr = await fetch(buildUrl(`/api/getremarksbystudentfilters?${fp}`), { headers });
          const fd = await fr.json();
          const frec = Array.isArray(fd?.data) ? fd.data[0] : (Array.isArray(fd) ? fd[0] : (fd?.data || null));
          finalRemark = frec?.remarks || '';
        } catch (e) { /* no final remark */ }
        if (cancelled) return;
        setResCardMarks({ subjects: subs.map(s => s.subjectName), totals, obtained, remarks, finalRemark });
      } catch (e) {
        console.error('Error loading single card subject marks:', e);
        if (!cancelled) setResCardMarks({ subjects: [], totals: {}, obtained: {} });
      }
    })();
    return () => { cancelled = true; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [resCardCtx]);

  /* When a student's card opens, load the real per-subject main-exam marks. */
  useEffect(() => {
    if (!cbrCardCtx) { setCbrCardMarks(null); return undefined; }
    setCbrCardMarks(null); // pehle clear — sirf API data dikhe, static/stale flash na ho
    const grp = cbrResults.find(g => g.id === cbrCardCtx.classId);
    const st  = grp?.students.find(s => s.rollNo === cbrCardCtx.studentRollNo);
    if (!grp || !st) return undefined;
    let cancelled = false;
    (async () => {
      try {
        /* The main exam may belong to any term — resolve its term from the
           all-term list (load it if not ready), then fall back to the current. */
        let pool = cbrAllExams;
        if (!pool.length) pool = await loadAllTermExams();
        const mainEx = pool.find(e => String(e.selectExam) === String(grp.mainExamID))
          || pool.find(e => e.name === grp.mainExam);
        const termID = mainEx?.termID ?? selectedTermId;
        let subs = await cbrApi.getMainExamSubjects({ classID: grp.classID, sectionID: grp.sectionID, termID, examID: grp.mainExamID });
        let withMarks = true;
        /* Main exam has no subjects → fall back to a sub exam's subject list and
           leave the marks empty. */
        if ((!subs || !subs.length) && grp.subExamIDs?.length) {
          const subExamId = grp.subExamIDs[0];
          const subTermID = pool.find(e => String(e.selectExam) === String(subExamId))?.termID ?? termID;
          subs = await cbrApi.getMainExamSubjects({ classID: grp.classID, sectionID: grp.sectionID, termID: subTermID, examID: subExamId });
          withMarks = false;
        }
        subs = subs || [];
        // getMainExamSubjects returns subjectName=null, so resolve names by subjectID.
        const nameMap = {};
        try {
          const syl = await getSyllabusSubjects(grp.classID, grp.sectionID);
          (syl || []).forEach(s => { nameMap[s.subjectID] = s.subjectName; });
        } catch (e) { /* keep going with whatever names we have */ }
        subs = subs.map(su => ({
          ...su,
          subjectName: su.subjectName || nameMap[su.subjectID] || `Subject ${su.subjectID}`,
        }));
        const token = sessionStorage.getItem('token');
        const headers = { Authorization: `Bearer ${token}`, Accept: 'application/json' };
        const obtained = {}, totals = {}, remarks = {};
        if (withMarks) {
          // Direct fetch taa-ke obtain + remarks dono mil sakein (Comment column ke liye)
          await Promise.all(subs.map(async su => {
            try {
              const p = new URLSearchParams({
                classID: String(grp.classID), termID: String(termID ?? ''), ExamID: String(grp.mainExamID),
                SubjectID: String(su.subjectID), StudentID: String(st.studentID), sectionID: String(grp.sectionID), pageNo: '1',
              });
              const r = await fetch(buildUrl(`/api/getsauploadmarksbyclassandtermandexamandsubject?${p}`), { headers });
              const d = await r.json();
              const rec = Array.isArray(d) ? d[0] : (d?.data?.[0] || null);
              obtained[su.subjectName] = Number(rec?.obtainMarks ?? rec?.obtainedMarks ?? 0);
              totals[su.subjectName]   = Number(rec?.totalMarks ?? su.totalMarks ?? 0);
              if (rec?.remarks) remarks[su.subjectName] = rec.remarks;
            } catch { obtained[su.subjectName] = 0; totals[su.subjectName] = Number(su.totalMarks ?? 0); }
          }));
        } else {
          subs.forEach(su => { obtained[su.subjectName] = ''; totals[su.subjectName] = su.totalMarks; });
        }
        // Student ka FINAL remark (getremarksbystudentfilters) → card ke Final Remarks mein
        let finalRemark = '';
        try {
          const branchID = sessionStorage.getItem('branchID');
          const fp = new URLSearchParams({
            branchID: String(branchID), classID: String(grp.classID), sectionID: String(grp.sectionID),
            examID: String(grp.mainExamID), termID: String(termID ?? ''), studentID: String(st.studentID),
            pageNo: '1', pageCount: '20',
          });
          const fr = await fetch(buildUrl(`/api/getremarksbystudentfilters?${fp}`), { headers });
          const fd = await fr.json();
          const frec = Array.isArray(fd?.data) ? fd.data[0] : (Array.isArray(fd) ? fd[0] : (fd?.data || null));
          finalRemark = frec?.remarks || '';
        } catch (e) { /* no final remark */ }
        if (cancelled) return;
        setCbrCardMarks({ subjects: subs.map(s => s.subjectName), totals, obtained, remarks, finalRemark });
      } catch (e) {
        console.error('Error loading card subject marks:', e);
        if (!cancelled) setCbrCardMarks({ subjects: [], totals: {}, obtained: {} });
      }
    })();
    return () => { cancelled = true; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [cbrCardCtx]);

  /* ── Result History state ── */
  const [rhSearchQ, setRhSearchQ]             = useState('');
  const [rhFilterSession, setRhFilterSession] = useState('');
  const [rhFilterClass, setRhFilterClass]     = useState('');
  const [rhFilterSection, setRhFilterSection] = useState('');
  const [rhFilterExam, setRhFilterExam]       = useState('');
  const [rhSearchFocused, setRhSearchFocused] = useState(false);
  const [rhActiveStudent, setRhActiveStudent] = useState(null); // student object
  const [rhCardCtx, setRhCardCtx]             = useState(null); // { student, result }
  const [rhReportReq, setRhReportReq]         = useState(null); // { student, type:'card'|'history'|'progress'|'comparison'|'attendance', result? }
  const [rhExams, setRhExams]                 = useState([]);   // student-click par fetched exams (examName/termName)
  const [rhExamsLoading, setRhExamsLoading]   = useState(false);
  const [rhCardMarks, setRhCardMarks]         = useState(null); // View card ke liye real per-subject marks
  const [rhExamScores, setRhExamScores]       = useState({});   // { [exam.id]: overall % } exam history ke liye
  const [rhStudentSummaries, setRhStudentSummaries] = useState({}); // { [studentId]: { avgPct, best, count, trend, grade } } card list ke liye

  // Student par click karte hi us ki class/section ke exams fetch karo (result history).
  const loadStudentExams = async (st) => {
    try {
      setRhExamsLoading(true);
      const branchID  = sessionStorage.getItem('branchID');
      const token     = sessionStorage.getItem('token');
      const classID   = st.gradeId   ?? st.classID   ?? st.classId   ?? '';
      const sectionID = st.sectionId ?? st.sectionID ?? '';
      const url = buildUrl(`/api/getexamsbybranchclassidsectionid?branchID=${branchID}&classID=${classID}&sectionID=${sectionID}&pageNo=1`);
      const res = await fetch(url, { headers: { Authorization: `Bearer ${token}`, Accept: '*/*' } });
      const data = await res.json();
      setRhExams(Array.isArray(data?.data) ? data.data : (Array.isArray(data) ? data : []));
    } catch (e) {
      console.error('Could not load student exam history', e);
      setRhExams([]);
    } finally {
      setRhExamsLoading(false);
    }
  };

  // Jab koi student active ho → uske exams load karo; band karte hi clear.
  useEffect(() => {
    if (rhActiveStudent) loadStudentExams(rhActiveStudent);
    else setRhExams([]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rhActiveStudent]);

  /* Result History "View" card khulte hi us exam ka REAL per-subject record load karo:
       1) getSyllabusSubjects → class/section ke saare subjects (Math / Science 3 / KG)
       2) har subject ke against getsauploadmarksbyclassandtermandexamandsubject → obtain + total marks
     (Single assessment card bhi yahi marks API use karta hai). */
  useEffect(() => {
    if (!rhCardCtx) { setRhCardMarks(null); return undefined; }
    setRhCardMarks(null); // pehle clear karo taa-ke purana/static data flash na ho (sirf API data dikhe)
    const { result, student } = rhCardCtx;
    const classID    = result?.classID   ?? student?.gradeId   ?? student?.classID;
    const sectionID  = result?.sectionID ?? student?.sectionId ?? student?.sectionID;
    const examID     = result?.selectExam;
    const termID     = result?.termID;
    const studentId  = student?.id;
    if (!classID || !sectionID || !examID) { setRhCardMarks({ subjects: [], totals: {}, obtained: {} }); return undefined; }
    let cancelled = false;
    (async () => {
      try {
        const token = sessionStorage.getItem('token');
        const headers = { Authorization: `Bearer ${token}`, Accept: 'application/json' };
        // 1) Subjects list (Math / Science 3 / KG) — reliably subjects deta hai
        const subs = (await getSyllabusSubjects(classID, sectionID)) || [];
        // 2) Har subject ke against student ke obtain/total marks
        const records = await Promise.all(subs.map(async su => {
          try {
            const p = new URLSearchParams({
              classID: String(classID), termID: String(termID ?? ''), ExamID: String(examID),
              SubjectID: String(su.subjectID), StudentID: String(studentId),
              sectionID: String(sectionID), pageNo: '1',
            });
            const r = await fetch(buildUrl(`/api/getsauploadmarksbyclassandtermandexamandsubject?${p}`), { headers });
            const d = await r.json();
            const rec = Array.isArray(d) ? d[0] : (d?.data?.[0] || null);
            return { su, rec };
          } catch { return { su, rec: null }; }
        }));
        if (cancelled) return;
        const obtained = {}, totals = {}, remarks = {};
        records.forEach(({ su, rec }) => {
          const name = su.subjectName || `Subject ${su.subjectID}`;
          obtained[name] = Number(rec?.obtainMarks ?? rec?.obtainedMarks ?? 0);
          totals[name]   = Number(rec?.totalMarks ?? su.totalMarks ?? 0);
          if (rec?.remarks) remarks[name] = rec.remarks;   // saved remarks → Comment column
        });
        // 3) Student ka FINAL remark (getremarksbystudentfilters) → card ke Final Remarks mein
        let finalRemark = '';
        try {
          const branchID = sessionStorage.getItem('branchID');
          const fp = new URLSearchParams({
            branchID: String(branchID), classID: String(classID), sectionID: String(sectionID),
            examID: String(examID), termID: String(termID ?? ''), studentID: String(studentId),
            pageNo: '1', pageCount: '20',
          });
          const fr = await fetch(buildUrl(`/api/getremarksbystudentfilters?${fp}`), { headers });
          const fd = await fr.json();
          const frec = Array.isArray(fd?.data) ? fd.data[0] : (Array.isArray(fd) ? fd[0] : (fd?.data || null));
          finalRemark = frec?.remarks || '';
        } catch (e) { /* no final remark */ }
        if (cancelled) return;
        setRhCardMarks({ subjects: subs.map(s => s.subjectName), totals, obtained, remarks, finalRemark });
      } catch (e) {
        console.error('Error loading result-history card subject marks:', e);
        if (!cancelled) setRhCardMarks({ subjects: [], totals: {}, obtained: {} });
      }
    })();
    return () => { cancelled = true; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [rhCardCtx]);

  /* Exam history ke har exam ka overall % compute karo (score bar / grade / Performance Trends ke liye):
     har exam ke saare subjects ke obtain/total marks jodo → % = sum(obtain)/sum(total)*100. */
  useEffect(() => {
    if (!rhActiveStudent || !rhExams.length) { setRhExamScores({}); return undefined; }
    const st = rhActiveStudent;
    const classID = st.gradeId ?? st.classID;
    const sectionID = st.sectionId ?? st.sectionID;
    const studentId = st.id;
    let cancelled = false;
    (async () => {
      try {
        const token = sessionStorage.getItem('token');
        const headers = { Authorization: `Bearer ${token}`, Accept: 'application/json' };
        const subs = (await getSyllabusSubjects(classID, sectionID).catch(() => [])) || [];
        const scores = {};
        await Promise.all(rhExams.map(async ex => {
          let obt = 0, tot = 0;
          await Promise.all(subs.map(async su => {
            try {
              const p = new URLSearchParams({
                classID: String(classID), termID: String(ex.termID ?? ''), ExamID: String(ex.selectExam),
                SubjectID: String(su.subjectID), StudentID: String(studentId), sectionID: String(sectionID), pageNo: '1',
              });
              const r = await fetch(buildUrl(`/api/getsauploadmarksbyclassandtermandexamandsubject?${p}`), { headers });
              const d = await r.json();
              const rec = Array.isArray(d) ? d[0] : (d?.data?.[0] || null);
              if (rec) { obt += Number(rec.obtainMarks ?? rec.obtainedMarks ?? 0); tot += Number(rec.totalMarks ?? 0); }
            } catch { /* skip subject */ }
          }));
          scores[ex.id] = tot > 0 ? Math.round((obt / tot) * 100) : 0;
        }));
        if (!cancelled) setRhExamScores(scores);
      } catch (e) {
        console.error('Error computing exam history scores:', e);
        if (!cancelled) setRhExamScores({});
      }
    })();
    return () => { cancelled = true; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [rhExams, rhActiveStudent]);

  /* Result History cards ke liye har student ki avg/best/trend calculation pehle se load karo
     (wahi exams + marks APIs). Har section ke exams/subjects ek baar fetch hote hain, phir
     har student ke per-exam % se avg/best/trend banta hai. Card jaise jaise ready hote jaate
     hain progressively bhar jaate hain. */
  useEffect(() => {
    const cs = rhData.classSection?.data;
    if (!cs || !cs.length) { setRhStudentSummaries({}); return undefined; }
    let cancelled = false;
    (async () => {
      try {
        const branchID = sessionStorage.getItem('branchID');
        const token    = sessionStorage.getItem('token');
        const headers  = { Authorization: `Bearer ${token}`, Accept: 'application/json' };
        for (const cls of cs) {
          for (const sec of (cls.sections || [])) {
            if (cancelled) return;
            const classID = cls.id, sectionID = sec.sectionID;
            const students = sec.students || [];
            if (!students.length) continue;
            // exams + subjects: section ke liye ek hi baar
